Rule.Source:

import sailpoint.api.SailPointContext;
import sailpoint.api.SailPointFactory;
import sailpoint.object.Custom;

SailPointContext privvy = null;
try {
    Custom obj1 = new Custom();
    obj1.setName("Without privateCtx");
    context.saveObject(obj1);
    context.commitTransaction();

    privvy = SailPointFactory.createPrivateContext();
    Custom obj2 = new Custom();
    obj2.setName("With privateCtx");
    privvy.saveObject(obj2);
    privvy.commitTransaction();

} finally {
    if (privvy != null) SailPointFactory.releasePrivateContext(privvy);
}
